insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position) values ('f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 'caja-sorpresa', 'Caja sorpresa', 'Un kit nuevo cada mes', 'No sabrás qué receta te toca hasta abrir la caja. Pago por adelantado de 1, 3 o 6 meses.', null, 'almendra', '/demo/products/sorpresa-1.jpg', 4) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('72475df3-538b-4bb6-9092-e4798f8a662c', 'kit-wraps-crujientes', 'Kit Wraps crujientes', 'Wraps de pollo y verduras con salsa de yogur y lima. Sin fuego.', 'Tu primera receta sin encender nada. Tortillas de trigo, mezcla de especias suave y la salsa de yogur y lima que hace que todo sepa a restaurante. Tú pones el pollo asado y las verduras; nosotros, todo lo demás y un vídeo paso a paso.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 120, '{"minutes":15,"difficulty":1,"heat":"sin-fuego"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, leche. Puede contener trazas de sésamo."},{"label":"Lo que pones tú","value":"Pollo asado, lechuga, tomate y un yogur natural."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array[]::text[], array['6 tortillas de trigo', 'Mezcla de especias suave', 'Base para salsa de yogur y lima', 'Tarjeta de receta con QR']::text[], now() - interval '120 days', now() - interval '120 days') on conflict (id) do nothing;
