insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('a9371802-306a-4621-9509-c25cc6b33d33', 'kit-bowl-arcoiris', 'Kit Bowl arcoíris', 'Garbanzos especiados, cuscús y verduras de todos los colores.', 'Un bowl que entra por los ojos. El cuscús se hace en el microondas en cinco minutos, los garbanzos llevan nuestra mezcla de especias tostadas y el aliño de tahini lo une todo. Cien por cien vegetal.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', true, true, null, 95, '{"minutes":15,"difficulty":1,"heat":"microondas"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, sésamo."},{"label":"Lo que pones tú","value":"Un aguacate, tomates cherry, lombarda y zanahoria."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['Cuscús', 'Garbanzos cocidos en conserva', 'Especias tostadas', 'Aliño de tahini', 'Tarjeta de receta con QR']::text[], now() - interval '90 days', now() - interval '90 days') on conflict (id) do nothing;
