insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('beae607c-9233-4059-8699-6aa67c8de783', 'kit-parfait-frutos-rojos', 'Kit Parfait de frutos rojos', 'Granola crujiente, yogur y frutos rojos. Desayuno de diez.', 'Capas de yogur, granola con miel y frutos rojos liofilizados que recuperan todo su sabor. Montas cuatro tarros en diez minutos y tienes desayuno o merienda para varios días.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, 'Oferta', 80, '{"minutes":10,"difficulty":1,"heat":"sin-fuego"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten (avena), frutos de cáscara."},{"label":"Lo que pones tú","value":"Yogur natural o griego."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegetariano']::text[], array['Granola con miel', 'Frutos rojos liofilizados', 'Semillas de chía', 'Tarjeta de receta con QR']::text[], now() - interval '60 days', now() - interval '60 days') on conflict (id) do nothing;
