insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('11711508-bff7-4893-8d40-de6e0e3c4111', 'kit-tostadas-aguacate', 'Kit Tostadas de aguacate y huevo', 'Pan de masa madre, aguacate y huevo poché al microondas.', 'El truco del huevo poché en taza que te va a cambiar los desayunos. Incluye pan de masa madre tostado, nuestra mezcla de semillas y chile suave, y la receta para clavar el punto del huevo en 60 segundos.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, 'Nuevo', 12, '{"minutes":12,"difficulty":1,"heat":"microondas"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, sésamo. Huevo (lo pones tú)."},{"label":"Lo que pones tú","value":"Dos aguacates y cuatro huevos."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegetariano']::text[], array['Pan de masa madre tostado', 'Mezcla de semillas y chile suave', 'Escamas de sal', 'Tarjeta de receta con QR']::text[], now() - interval '6 days', now() - interval '6 days') on conflict (id) do nothing;
