insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('629ead1c-9bd7-4841-b3b5-9b7a000c741f', 'kit-ramen-casero', 'Kit Ramen casero', 'Caldo de miso, fideos ramen y toppings. El que te convierte en chef.', 'Nuestro kit estrella. Fideos ramen de verdad, base de caldo de miso, aceite de chile y sésamo, alga nori y la receta para dejar los huevos marinados perfectos. Un bol que no tiene nada que envidiar al de tu restaurante favorito.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, 'Más vendido', 340, '{"minutes":35,"difficulty":2,"heat":"cazo"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, soja, sésamo."},{"label":"Lo que pones tú","value":"Huevos, cebolleta y la proteína que quieras (pollo, tofu o gambas)."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array[]::text[], array['Fideos ramen', 'Base de caldo de miso', 'Aceite de chile y sésamo', 'Alga nori', 'Salsa para marinar huevos', 'Tarjeta de receta con QR']::text[], now() - interval '150 days', now() - interval '150 days') on conflict (id) do nothing;
