insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('0c200051-60e5-4fc6-a384-c3bbeb69ff10', 'kit-tacos-al-pastor', 'Kit Tacos al pastor', 'Adobo de achiote, tortillas de maíz y salsa de piña.', 'Tacos de pollo marinado en adobo al pastor, hechos a la sartén. El kit trae el adobo, las tortillas de maíz y una salsa de piña con un punto picante. Fiesta asegurada.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, null, 175, '{"minutes":30,"difficulty":2,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Sin alérgenos de declaración obligatoria. Elaborado en instalaciones que manipulan gluten."},{"label":"Lo que pones tú","value":"Muslos de pollo, cebolla, cilantro y lima."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['picante', 'sin-gluten']::text[], array['12 tortillas de maíz', 'Adobo al pastor', 'Salsa de piña y chile', 'Tarjeta de receta con QR']::text[], now() - interval '100 days', now() - interval '100 days') on conflict (id) do nothing;
