insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('5ebf0ff0-8228-4e27-953e-2f2622f77a85', 'kit-tortitas-americanas', 'Kit Tortitas americanas', 'Esponjosas, altas y con sirope de arce. Domingo resuelto.', 'La mezcla seca ya está pesada: solo añades huevo y leche. Te enseñamos a controlar el fuego de la sartén para que salgan doradas y altísimas. Incluye sirope de arce y pepitas de chocolate.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 210, '{"minutes":25,"difficulty":2,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, leche. Puede contener trazas de frutos de cáscara."},{"label":"Lo que pones tú","value":"Dos huevos, leche y mantequilla."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegetariano']::text[], array['Mezcla para tortitas', 'Sirope de arce', 'Pepitas de chocolate', 'Tarjeta de receta con QR']::text[], now() - interval '130 days', now() - interval '130 days') on conflict (id) do nothing;
