insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('9cd23a54-a303-49f7-8245-387ac19888f5', 'kit-curry-rojo-thai', 'Kit Curry rojo tailandés', 'Pasta de curry, leche de coco y arroz jazmín.', 'Un viaje a Bangkok en 40 minutos. Pasta de curry rojo, leche de coco cremosa, salsa de pescado y arroz jazmín. Te enseñamos a equilibrar dulce, salado, ácido y picante como hacen en Tailandia.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', true, true, 'Nuevo', 30, '{"minutes":40,"difficulty":3,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Pescado, crustáceos."},{"label":"Lo que pones tú","value":"Pollo o salmón, un pimiento rojo y lima."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['picante', 'sin-gluten']::text[], array['Pasta de curry rojo', 'Leche de coco', 'Arroz jazmín', 'Salsa de pescado', 'Tarjeta de receta con QR']::text[], now() - interval '4 days', now() - interval '4 days') on conflict (id) do nothing;
