insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('0a53aa7d-4cf2-4f64-847a-ecd3b303d8ca', 'kit-butter-chicken', 'Kit Butter chicken con naan', 'Pollo en salsa de tomate, mantequilla y garam masala.', 'El plato indio que gusta a todo el mundo. Marinado de yogur y especias, salsa cremosa de tomate y mantequilla, y la mezcla para hacer naan en la sartén. Nivel 3 porque hay que coordinar tres elaboraciones a la vez.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 150, '{"minutes":50,"difficulty":3,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, leche."},{"label":"Lo que pones tú","value":"Muslos de pollo, yogur natural, mantequilla y nata."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array[]::text[], array['Garam masala', 'Especias para el marinado', 'Tomate concentrado', 'Mezcla para naan', 'Tarjeta de receta con QR']::text[], now() - interval '70 days', now() - interval '70 days') on conflict (id) do nothing;
