insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('c4cf16d7-722c-4932-a9b3-d2fdc678c730', 'kit-gyozas-caseras', 'Kit Gyozas caseras', 'Obleas, relleno y salsa ponzu. Aprende el pliegue perfecto.', 'El reto del nivel 3: cerrar gyozas con sus pliegues. Trae obleas, la mezcla de especias para el relleno y salsa ponzu para mojar. En el vídeo te enseñamos el pliegue paso a paso y la técnica de vapor y sartén.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, 'Nuevo', 18, '{"minutes":60,"difficulty":3,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, soja, sésamo."},{"label":"Lo que pones tú","value":"Carne picada o tofu, col y cebolleta."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array[]::text[], array['30 obleas para gyozas', 'Especias para el relleno', 'Salsa ponzu', 'Aceite de sésamo', 'Tarjeta de receta con QR']::text[], now() - interval '9 days', now() - interval '9 days') on conflict (id) do nothing;
