insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('6c0cf2f9-8833-4fa4-8699-8cbb8feb3e5e', 'kit-pizza-napolitana', 'Kit Pizza napolitana', 'Masa de larga fermentación, tomate San Marzano y orégano.', 'Harina tipo 00, levadura y la técnica de la masa con reposo largo. Estiras a mano, horneas a máxima potencia y consigues un borde inflado y tostado. Incluye tomate San Marzano y orégano siciliano.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 260, '{"minutes":45,"difficulty":3,"heat":"horno"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten."},{"label":"Lo que pones tú","value":"Mozzarella, albahaca fresca y aceite de oliva."},{"label":"Tiempo de reposo","value":"La masa necesita entre 8 y 24 horas de reposo en nevera."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegetariano']::text[], array['Harina tipo 00', 'Levadura seca', 'Tomate San Marzano', 'Orégano siciliano', 'Tarjeta de receta con QR']::text[], now() - interval '140 days', now() - interval '140 days') on conflict (id) do nothing;
