insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('8d6b83ec-d10f-4c29-a237-b8921c573207', 'kit-yakisoba', 'Kit Yakisoba', 'Fideos salteados al wok con salsa yakisoba y verduras.', 'Fideos de trigo salteados a fuego fuerte con verduras crujientes y salsa yakisoba casera. Aprendes la técnica del salteado rápido: todo cortado antes, sartén muy caliente y movimiento constante.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 88, '{"minutes":25,"difficulty":3,"heat":"sarten"}'::jsonb, '[{"label":"Alérgenos","value":"Gluten, soja, sésamo."},{"label":"Lo que pones tú","value":"Col, zanahoria, cebolla y pimiento."},{"label":"Conservación","value":"Lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta paso a paso con QR al vídeo de la receta."}]'::jsonb, array['vegano']::text[], array['Fideos de trigo', 'Salsa yakisoba', 'Jengibre deshidratado', 'Sésamo tostado', 'Tarjeta de receta con QR']::text[], now() - interval '50 days', now() - interval '50 days') on conflict (id) do nothing;
