insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, includes, published_at, created_at) values ('801b9aff-7671-4c0c-9f6f-d469714e5aa6', 'caja-sorpresa', 'Caja sorpresa', 'Un kit nuevo cada mes. No sabrás cuál hasta abrir la caja.', 'Cada mes enviamos un kit distinto, elegido entre los tres niveles y con recetas que no están en la tienda. Pagas por adelantado 1, 3 o 6 meses (cuantos más, más barato) y la recibes la primera semana de cada mes. No es una suscripción: no se renueva sola.', 'f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 1000, 'published', true, true, null, 64, '{"minutes":40,"difficulty":2,"heat":"sarten"}'::jsonb, '[{"label":"Envíos","value":"La primera semana de cada mes, a la misma dirección."},{"label":"Renovación","value":"Sin renovación automática."},{"label":"Alérgenos","value":"Variables según el kit. Te avisamos por email antes de cada envío."}]'::jsonb, array[]::text[], array['Un kit sorpresa al mes', 'Receta exclusiva con QR', 'Pegatina de nivel para coleccionar']::text[], now() - interval '30 days', now() - interval '30 days') on conflict (id) do nothing;
